use kujo::{interpreter::{Interpreter,Value},lexer::tokenize,parser::Parser};
fn main() {
    let mut runtime=Interpreter::new();
    runtime.eval_stmts(&Parser::new(tokenize("mut fixed := 11 func factory() { const fixed := 7 func step() { return fixed } return step } let step := factory()").unwrap()).parse());
    let Some(Value::Function(_,_,Some(owner)))=runtime.env.get("step") else {panic!("closure missing")};
    {
        let mut owner=owner.lock().unwrap();
        let local=owner.scopes.iter_mut().skip(1).rev().find(|s|s.contains_key("fixed")).expect("local missing");
        local.remove("fixed");
        owner.scopes[0].insert("fixed".into(),Value::Int(11));
        assert!(matches!(owner.get("fixed"),Some(Value::Int(11))));
    }
    runtime.eval_stmts(&Parser::new(tokenize("let result := step()").unwrap()).parse());
    println!("result={:?}",runtime.env.get("result"));
    assert!(matches!(runtime.env.get("result"),Some(Value::Int(11))));
}
